"""Generate an approval summary that links to, but never copies, canonical wording."""

import argparse

from .editorial_candidates import CANDIDATES
from .indexes import load_function_by_id
from .locale import LocaleCatalog
from .paths import REPO_ROOT

OUTPUT = "docs/EDITORIAL_CANDIDATE_REVIEW.md"


def render():
    catalog = LocaleCatalog()
    lines = [
        "# Canonical editorial approval summary",
        "",
        "Generated by `python -m ocf_tools.editorial_review`. Function words and procedures are owned only by the linked canonical locale resource; this report does not copy narration or create another authority.",
        "",
        "Recorded narration approval is not listening approval, rights clearance, or release approval.",
        "",
    ]
    for name, identity in CANDIDATES.items():
        record = load_function_by_id(identity)
        if record is None:
            raise ValueError("canonical function is missing: " + identity)
        localized = catalog.require("en-US").localized_functions[identity]
        approval = localized.get("record_metadata", {}).get("editorial_approval")
        if not approval:
            raise ValueError("canonical editorial approval metadata is missing: " + identity)
        path = record.path.relative_to(REPO_ROOT).as_posix()
        lines.extend(
            [
                f"## {record.canonical_name} (`{identity}`)",
                "",
                f"- Canonical authority: [`{path}`](../{path})",
                f"- Approval: `{approval['approval_id']}` / `{approval['decision']}`; response `{approval['user_response']}`.",
                f"- Presented snapshot SHA-256: `{approval['presented_snapshot_sha256']}` (verification metadata only; no snapshot copy is retained).",
                f"- Canonical narration entries: {len(approval['resolved_text_sha256'])}; exact resolved-text hashes are stored with the approval metadata.",
                "- Listening approval: no. Release ready: no.",
                "",
            ]
        )
    return "\n".join(lines)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    path = REPO_ROOT / OUTPUT
    expected = render()
    if args.check:
        return int(not path.is_file() or path.read_text(encoding="utf-8") != expected)
    path.write_text(expected, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
